/// REG-preconfig-and-queue (gh-1781): the executable must resolve the
/// provider queue BEFORE the secure-store preload and the legacy key gate,
/// thread `queueResolved` into [startupApiKey] and `queueSecrets` into
/// [buildSecretRedactor], and keep the legacy `FA_PROVIDER_*` headless
/// missing-key failure byte-identical. Hermetic source grep over the
/// executable library (same discipline as the guard above) + the lib-side
/// paired assertions in test/cli/startup_test.dart.
void main() {
  final source = _executableSource();

  // Boot order: the queue scope resolution precedes BOTH the preload and
  // the key gate (a queue-only boot satisfies the gate — AC1), and the
  // queue runtime build sits between the preload (it consumes the secrets
  // snapshot) and the gate (an all-keyless queue fails with the queue
  // error first — AC3).
  int indexOf2(String needle, int start) => source.indexOf(needle, start);
  final queueResolve = source.indexOf('resolveProviderQueueAtBoot(');
  final preload = source.indexOf('keyCache.preload(');
  final keyGate = source.indexOf('startupApiKey(');
  final queueBuild = source.indexOf('ProviderQueueRuntime.build(');
  test('REG: the queue is resolved before keyCache.preload and the key '
      'gate (AC1/AC3)', () {
    expect(queueResolve, greaterThan(0), reason: 'queue scope resolution wired');
    expect(preload, greaterThan(queueResolve),
        reason: 'keyCache.preload must run AFTER the queue resolution so '
            'queue key names feed the preload set');
    expect(queueBuild, greaterThan(preload),
        reason: 'ProviderQueueRuntime.build consumes collectQueueSecrets, '
            'which reads the preloaded store snapshot');
    expect(keyGate, greaterThan(queueBuild),
        reason: 'the legacy key gate must see the built queue (queueResolved) '
            'and lose to the queue error when every entry is keyless');
  });

  test('REG: queueResolved threads into startupApiKey and queueSecrets '
      'into buildSecretRedactor (I1/I5)', () {
    expect(
      source.contains('queueResolved: queueRuntime != null'),
      isTrue,
      reason: 'startupApiKey must receive the queue presence',
    );
    expect(
      source.contains('queueSecrets: queueSecrets'),
      isTrue,
      reason: 'buildSecretRedactor must receive the queue secrets snapshot',
    );
    expect(
      source.contains('queueEntries: queueResolution?.entries'),
      isTrue,
      reason: 'secureKeyPreloadNames must receive the resolved queue entries',
    );
  });

  test('REG: the boot model identity follows the queue head when the '
      'launch pinned nothing (I6)', () {
    expect(
      source.contains('queueOwnsBootModel('),
      isTrue,
      reason: 'the boot-model override must ride the shared pure predicate',
    );
    final override = source.indexOf('queueOwnsBootModel(');
    final assign = source.indexOf('model = queueRuntime.streamFunction.currentModel');
    expect(assign, greaterThan(override),
        reason: 'the queue-head assignment must be gated by the predicate');
  });
}

